CREATE TABLE IF NOT EXISTS produtos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nome TEXT NOT NULL,
    preco REAL
);

with st.form("form_produto"):
    nome = st.text_input("Nome")
    preco = st.number_input("Preço", min_value=0.0, step=0.5)
    enviar = st.form_submit_button("Cadastrar")

if enviar:
    if not nome:
        st.error("Informe o nome.")
    elif preco <= 0:
        st.error("O preço deve ser maior que zero.")
    else:
        inserir_produto(nome, preco)
        st.success(f"{nome} cadastrado!")

produtos = ler_produtos()
opcoes = {p["id"]: f'{p["id"]} - {p["nome"]}' for p in produtos}
id_sel = st.selectbox("Produto", list(opcoes), format_func=lambda k: opcoes[k])

if id_sel:
    escolhido = next(p for p in produtos if p["id"] == id_sel)
    st.write(escolhido)

def excluir_produto(id_produto):
    conn = get_db_connection()
    conn.execute("DELETE FROM produtos WHERE id = ?", (id_produto,))
    conn.commit()

if id_sel:
    confirmar = st.checkbox("Confirmo que quero excluir este produto")
    if st.button("Excluir", type="primary", disabled=not confirmar):
        excluir_produto(id_sel)
        st.success("Produto excluído!")

@st.cache_resource
def get_db_connection():
    conn = sqlite3.connect("dados_crud.db", check_same_thread=False)
    conn.row_factory = sqlite3.Row
    return conn          # sem conn.close() em nenhum lugar do projeto
